SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY A.CREATE_CHECK ASC, A.DID_DOWNCHECK ASC) AS RNUM, TB.* FROM ( SELECT A.BASIC_SCHEDULE_SEQ, A.CENTER_ID, B.CENTER_NM, A.BASIC_CODE, C.BASIC_GROUP_NM, A.CREATE_CHECK, CASE A.CREATE_CHECK WHEN 'N' THEN '00000000' ELSE TO_CHAR(A.CREATE_REGDATE, 'YYYY-MM-DD HH24:MI:SS') END AS CREATE_REGDATE, A.DID_DOWNCHECK, A.DID_DOWNLOADDATE FROM TB_BASICSCHEDULE A JOIN TB_CENTERINFO B ON A.CENTER_ID = B.CENTER_ID JOIN TB_BRODBASICGROUP C ON A.BASIC_CODE = C.BASIC_CODE WHERE 1=1
AND A.BASIC_CODE = #{basicCode}
AND A.CREATE_CHECK = #{createCheck}
AND A.DID_DOWNCHECK = #{didDowncheck}
) TB ) TA WHERE TA.RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

SELECT COALESCE(COUNT(*), 0)
FROM TB_BASICSCHEDULE A
JOIN TB_CENTERINFO B ON A.CENTER_ID = B.CENTER_ID
JOIN TB_BRODBASICGROUP C ON A.BASIC_CODE = C.BASIC_CODE
WHERE 1=1

    AND A.BASIC_CODE = #{basicCode}


    AND A.CREATE_CHECK = #{createCheck}


    AND A.DID_DOWNCHECK = #{didDowncheck}

