UPDATE TB_BASICSCHEDULE SET
                            BASIC_CODE = #{basicCode},
                            CREATE_CHECK = #{createCheck}
WHERE CENTER_ID = #{centerId}

UPDATE TB_BASICSCHEDULE SET
    CREATE_CHECK = #{createCheck}
WHERE BASIC_CODE = #{basicCode}
  AND CREATE_CHECK = #{preCreateCheck}

UPDATE TB_BASICSCHEDULE SET
    CREATE_CHECK = #{createCheck}
WHERE CENTER_ID = #{centerId}
  AND CREATE_CHECK = 'Y'

UPDATE TB_BASICSCHEDULE SET
                            DID_DOWNCHECK = #{didDowncheck},
                            DID_DOWNLOADDATE = NOW()
WHERE CENTER_ID = #{centerId}
  AND BASIC_CODE = #{basicCode}
  AND CREATE_CHECK = 'Y'

UPDATE TB_BASICSCHEDULE SET
    BASIC_CODE = #{basicCode}
WHERE BASIC_SCHEDULE_SEQ = #{basicScheduleSeq}

UPDATE TB_CENTERINFO SET
    BROD_CODE = #{basicCode}
WHERE CENTER_ID = #{centerId}

UPDATE TB_CENTERINFO SET
    BROD_CODE = NULL
WHERE BROD_CODE = #{basicCode}

